INSERT INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, description, source_book)
VALUES
  ('magazine-clip-pouch-automatic-pistol-nb', 'Magazine Clip Pouch (Automatic Pistol)', 'nightbane', 'gear', NULL, 10, '$10 for 2 clips, $16 for 4', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A specially designed ammo pouch for 2 (slimline) or 4 (heavy-duty) clips. Choice of camouflage, green, khaki or black. The 2-clip price is stored and cost_note carries both.', 'Nightbane RPG p.223'),
  ('magazine-clip-pouch-sub-machinegun-nb', 'Magazine Clip Pouch (Sub-Machinegun)', 'nightbane', 'gear', NULL, 12, '$12 for 2 cells, $18 for 4', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A specially designed ammo pouch for 2 (slimline) or 4 (heavy-duty) clips. Choice of camouflage, green, khaki or black. The 2-clip price is stored and cost_note carries both.', 'Nightbane RPG p.223'),
  ('magazine-clip-pouch-5-56mm-assault-rifle-20-round-nb', 'Magazine Clip Pouch (5.56mm Assault Rifle, 20-round)', 'nightbane', 'gear', NULL, 14, '$14 for 2 clips, $20 for 4', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A specially designed ammo pouch for 2 (slimline) or 4 (heavy-duty) clips. Choice of camouflage, green, khaki or black. The 2-clip price is stored and cost_note carries both.', 'Nightbane RPG p.223'),
  ('magazine-clip-pouch-5-56mm-assault-rifle-30-round-nb', 'Magazine Clip Pouch (5.56mm Assault Rifle, 30-round)', 'nightbane', 'gear', NULL, 18, '$18 for 2 clips, $24 for 4', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A specially designed ammo pouch for 2 (slimline) or 4 (heavy-duty) clips. Choice of camouflage, green, khaki or black. The 2-clip price is stored and cost_note carries both.', 'Nightbane RPG p.223'),
  ('magazine-clip-pouch-7-62mm-assault-rifle-20-round-nb', 'Magazine Clip Pouch (7.62mm Assault Rifle, 20-round)', 'nightbane', 'gear', NULL, 18, '$18 for 2 clips, $22 for 4', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A specially designed ammo pouch for 2 (slimline) or 4 (heavy-duty) clips. Choice of camouflage, green, khaki or black. The 2-clip price is stored and cost_note carries both.', 'Nightbane RPG p.223'),
  ('magazine-clip-pouch-7-62mm-assault-rifle-30-round-nb', 'Magazine Clip Pouch (7.62mm Assault Rifle, 30-round)', 'nightbane', 'gear', NULL, 20, '$20 for 2 clips, $26 for 4', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A specially designed ammo pouch for 2 (slimline) or 4 (heavy-duty) clips. Choice of camouflage, green, khaki or black. The 2-clip price is stored and cost_note carries both.', 'Nightbane RPG p.223'),
  ('magazine-ammo-bag-nb', 'Magazine Ammo Bag', 'nightbane', 'gear', NULL, 30, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Firearm accessories price list, printed 223.', 'Nightbane RPG p.223'),
  ('assault-rifle-case-nb', 'Assault Rifle Case', 'nightbane', 'gear', NULL, 70, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Firearm accessories price list, printed 223.', 'Nightbane RPG p.223'),
  ('rifle-case-nb', 'Rifle Case', 'nightbane', 'gear', NULL, 60, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Firearm accessories price list, printed 223.', 'Nightbane RPG p.223'),
  ('sub-machinegun-case-nb', 'Sub-Machinegun Case', 'nightbane', 'gear', NULL, 60, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Firearm accessories price list, printed 223.', 'Nightbane RPG p.223'),
  ('shotgun-bandoleer-nb', 'Shotgun Bandoleer', 'nightbane', 'gear', NULL, 24, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Brown leather with a heavy-duty brass belt buckle. The shotgun version holds 56 rounds and the 40mm grenade version 18. Printed 223 sets the $24 as its own sentence closing the entry, after both versions.', 'Nightbane RPG p.223'),
  ('wrist-cartridge-bandoleer-nb', 'Wrist Cartridge Bandoleer', 'nightbane', 'gear', NULL, 15, '$15 each', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Perfect for concealing 3 extra cartridges.', 'Nightbane RPG p.223'),
  ('metal-ammunition-box-50-caliber-nb', 'Metal Ammunition Box (.50 caliber)', 'nightbane', 'gear', NULL, 10, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A waterproof ammo box designed for easy storage and carrying.', 'Nightbane RPG p.223'),
  ('metal-ammunition-box-30-caliber-nb', 'Metal Ammunition Box (.30 caliber)', 'nightbane', 'gear', NULL, 8, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A waterproof ammo box designed for easy storage and carrying.', 'Nightbane RPG p.223'),
  ('field-gun-cleaning-kit-nb', 'Field Gun Cleaning Kit', 'nightbane', 'gear', NULL, 35, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A complete cleaning kit contained in its own pouch.', 'Nightbane RPG p.223'),
  ('gun-repair-kit-nb', 'Gun Repair Kit', 'nightbane', 'gear', 4, 250, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A 4lb kit. Each tool is fitted into a separate loop, with plenty of room for spare bolts, screws, springs and cleaning rods, in a 12 by 8 by 2 inch case. Attaches to a harness or is worn over the shoulder on the included strap.', 'Nightbane RPG p.223'),
  ('magazine-clips-nb', 'Magazine Clips', 'nightbane', 'gear', NULL, NULL, '$.89 each - BELOW THE RESOLUTION of an integer cost column, so it is recorded here rather than rounded to a dollar', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Any weapon, any size, from a 7-round pistol to a 30-round rifle.', 'Nightbane RPG p.223'),
  ('web-belt-military-nb', 'Web Belt (military)', 'nightbane', 'gear', NULL, 20, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A classic military belt complete with buckle and pouch fasteners, in camouflage, green or khaki. NOT the same item as the Web Belt with holster, ammo pouches and accessory clips on printed 222, which is $60.', 'Nightbane RPG p.223'),
  ('battle-harness-nb', 'Battle Harness', 'nightbane', 'gear', NULL, 120, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A combination of suspenders and belt designed to distribute the weight of ammo pouches and accessories. Camouflage, black, grey, brown, cream or khaki.', 'Nightbane RPG p.223'),
  ('battle-pack-nb', 'Battle Pack', 'nightbane', 'gear', NULL, 350, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A lightweight frame in heavy-duty, water resistant canvas, with multiple interior and exterior compartments and fasteners for exterior pouches and grenades. Camouflage, green or khaki.', 'Nightbane RPG p.223'),
  ('multi-purpose-pouch-nb', 'Multi-Purpose Pouch', 'nightbane', 'gear', NULL, 8, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'An all-around utility pouch designed for attachment to a web belt or battle harness.', 'Nightbane RPG p.223'),
  ('silencer-revolver-nb', 'Silencer (Revolver)', 'nightbane', 'gear', NULL, 350, 'Not available on the commercial market', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A barrel-like attachment which fits over the barrel of a gun to muffle the sound of the report. REDUCES RANGE BY 10%.', 'Nightbane RPG p.223'),
  ('silencer-automatic-pistol-nb', 'Silencer (Automatic Pistol)', 'nightbane', 'gear', NULL, 500, 'Not available on the commercial market', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A barrel-like attachment which fits over the barrel of a gun to muffle the sound of the report. REDUCES RANGE BY 10%.', 'Nightbane RPG p.223'),
  ('silencer-bolt-action-rifle-nb', 'Silencer (Bolt Action Rifle)', 'nightbane', 'gear', NULL, 600, 'Not available on the commercial market', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A barrel-like attachment which fits over the barrel of a gun to muffle the sound of the report. REDUCES RANGE BY 10%.', 'Nightbane RPG p.223'),
  ('silencer-automatic-rifle-nb', 'Silencer (Automatic Rifle)', 'nightbane', 'gear', NULL, 1500, 'Not available on the commercial market', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A barrel-like attachment which fits over the barrel of a gun to muffle the sound of the report. REDUCES RANGE BY 10%.', 'Nightbane RPG p.223'),
  ('silencer-sub-machinegun-nb', 'Silencer (Sub-Machinegun)', 'nightbane', 'gear', NULL, 2000, 'Not available on the commercial market', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A barrel-like attachment which fits over the barrel of a gun to muffle the sound of the report. REDUCES RANGE BY 10%.', 'Nightbane RPG p.223'),
  ('flash-suppressor-revolver-nb', 'Flash Suppressor (Revolver)', 'nightbane', 'gear', NULL, 250, 'Not available in the commercial market', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A barrel-shaped attachment that fits over the barrel of a gun or a silencer and masks the gun''s flash; usually used for covert night operations. REDUCES RANGE BY 15%, or 25% if both a silencer and a flash suppressor are used.', 'Nightbane RPG p.223'),
  ('flash-suppressor-automatic-pistol-nb', 'Flash Suppressor (Automatic Pistol)', 'nightbane', 'gear', NULL, 450, 'Not available in the commercial market', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A barrel-shaped attachment that fits over the barrel of a gun or a silencer and masks the gun''s flash; usually used for covert night operations. REDUCES RANGE BY 15%, or 25% if both a silencer and a flash suppressor are used.', 'Nightbane RPG p.223'),
  ('flash-suppressor-bolt-action-rifle-nb', 'Flash Suppressor (Bolt Action Rifle)', 'nightbane', 'gear', NULL, 1200, 'Not available in the commercial market', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A barrel-shaped attachment that fits over the barrel of a gun or a silencer and masks the gun''s flash; usually used for covert night operations. REDUCES RANGE BY 15%, or 25% if both a silencer and a flash suppressor are used.', 'Nightbane RPG p.223'),
  ('flash-suppressor-sub-machinegun-nb', 'Flash Suppressor (Sub-Machinegun)', 'nightbane', 'gear', NULL, 1600, 'Not available in the commercial market', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A barrel-shaped attachment that fits over the barrel of a gun or a silencer and masks the gun''s flash; usually used for covert night operations. REDUCES RANGE BY 15%, or 25% if both a silencer and a flash suppressor are used.', 'Nightbane RPG p.223'),
  ('ammunition-22-caliber-nb', 'Ammunition, .22 caliber', 'nightbane', 'gear', NULL, 12, 'per box of 100', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 223, AMMUNITION - prices per BOX OF 100.', 'Nightbane RPG p.223'),
  ('ammunition-32-caliber-nb', 'Ammunition, .32 caliber', 'nightbane', 'gear', NULL, 14, 'per box of 100', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 223, AMMUNITION - prices per BOX OF 100.', 'Nightbane RPG p.223'),
