  ('ammunition-5-56mm-rifle-nb', 'Ammunition, 5.56mm (rifle)', 'nightbane', 'gear', NULL, 40, 'per box of 100', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 223, AMMUNITION - prices per BOX OF 100.', 'Nightbane RPG p.223'),
