INSERT INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, description, source_book)
VALUES
  ('ammunition-tracer-cartridge-nb', 'Ammunition, Tracer Cartridge', 'nightbane', 'gear', NULL, 45, 'per box of 100', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 223, AMMUNITION - prices per BOX OF 100.', 'Nightbane RPG p.223'),
  ('ammunition-hollow-point-surcharge-nb', 'Ammunition, Hollow Point (surcharge)', 'nightbane', 'gear', NULL, 12, 'ADD $12.00 to the price of a box', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 223 gives this as an ADD-ON to the price of a box of 100, not a price of its own. The figure is the surcharge.', 'Nightbane RPG p.223'),
  ('ammunition-full-metal-jacketed-surcharge-nb', 'Ammunition, Full Metal Jacketed (surcharge)', 'nightbane', 'gear', NULL, 25, 'ADD $25.00 to the price of a box', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 223 gives this as an ADD-ON to the price of a box of 100, not a price of its own. The figure is the surcharge.', 'Nightbane RPG p.223'),
  ('ammunition-teflon-armor-piercing-surcharge-nb', 'Ammunition, Teflon armor piercing (surcharge)', 'nightbane', 'gear', NULL, 100, 'ADD $100.00; not available to the public', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 223 gives this as an ADD-ON to the price of a box of 100, not a price of its own. The figure is the surcharge. Printed 223 marks this with an asterisk: NOT available at the neighborhood gun shop, but can be tracked down through the black market and illegal arms dealers. The added price is a MINIMUM and can cost two or three times more.', 'Nightbane RPG p.223'),
  ('ammunition-exploding-shell-surcharge-nb', 'Ammunition, Exploding Shell (surcharge)', 'nightbane', 'gear', NULL, 200, 'ADD $200.00; not available to the public', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 223 gives this as an ADD-ON to the price of a box of 100, not a price of its own. The figure is the surcharge. Printed 223 marks this with an asterisk: NOT available at the neighborhood gun shop, but can be tracked down through the black market and illegal arms dealers. The added price is a MINIMUM and can cost two or three times more.', 'Nightbane RPG p.223'),
  ('ammunition-dum-dum-surcharge-nb', 'Ammunition, Dum Dum (surcharge)', 'nightbane', 'gear', NULL, 10, 'ADD $10.00 to $30.00; handmade, black market, any caliber', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 223 gives this as an ADD-ON to the price of a box of 100, not a price of its own. The figure is the surcharge. Printed 223 marks this with an asterisk: NOT available at the neighborhood gun shop, but can be tracked down through the black market and illegal arms dealers. The added price is a MINIMUM and can cost two or three times more.', 'Nightbane RPG p.223'),
  ('40mm-grenade-cartridge-nb', '40mm Grenade Cartridge', 'nightbane', 'gear', NULL, 700, '$700.00 per 100', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 223, AMMUNITION - prices per BOX OF 100. Printed 223 marks this with an asterisk: NOT available at the neighborhood gun shop, but can be tracked down through the black market and illegal arms dealers. The added price is a MINIMUM and can cost two or three times more.', 'Nightbane RPG p.223'),
  ('padded-or-quilt-armor-nb', 'Padded or Quilt Armor', 'nightbane', 'armor', 66, 175, NULL, NULL, 0, NULL, NULL, NULL, 8, 15, 'Ancient style. THE PRINTED WEIGHT IS 66lbs, heavier than the Plate armor four rows below it at 58lbs and almost certainly a book error for 6lbs. Confirmed on a 150 dpi render of printed 223: the page really says 66. Transcribed as printed rather than corrected. Table note: the costs reflect the rarity of manufacturers/builders and the time involved in construction; homemade armor is possible at half cost, with A.R. reduced by 2 and S.D.C. by 20%.', 'Nightbane RPG p.223'),
  ('soft-leather-armor-nb', 'Soft Leather Armor', 'nightbane', 'armor', 8, 300, NULL, NULL, 0, NULL, NULL, NULL, 9, 20, 'Ancient style, printed 223.', 'Nightbane RPG p.223'),
  ('studded-leather-armor-nb', 'Studded Leather Armor', 'nightbane', 'armor', 20, 600, NULL, NULL, 0, NULL, NULL, NULL, 12, 38, 'Ancient style, printed 223.', 'Nightbane RPG p.223'),
  ('chain-mail-nb', 'Chain Mail', 'nightbane', 'armor', 40, 900, NULL, NULL, 0, NULL, NULL, NULL, 13, 44, 'Ancient style, printed 223.', 'Nightbane RPG p.223'),
  ('scale-mail-nb', 'Scale Mail', 'nightbane', 'armor', 45, 1500, NULL, NULL, 0, NULL, NULL, NULL, 15, 75, 'Ancient style, printed 223.', 'Nightbane RPG p.223'),
  ('plate-and-mail-nb', 'Plate and Mail', 'nightbane', 'armor', 52, 2000, NULL, NULL, 0, NULL, NULL, NULL, 15, 100, 'Ancient style, printed 223.', 'Nightbane RPG p.223'),
  ('plate-armor-nb', 'Plate Armor', 'nightbane', 'armor', 58, 2800, NULL, NULL, 0, NULL, NULL, NULL, 16, 150, 'Ancient style, printed 223.', 'Nightbane RPG p.223'),
  ('plastic-plated-armor-nb', 'Plastic Plated Armor', 'nightbane', 'armor', 28, 3000, NULL, NULL, 0, NULL, NULL, NULL, 13, 80, 'Ancient style, printed 223.', 'Nightbane RPG p.223'),
  ('concealed-armor-nb', 'Concealed Armor', 'nightbane', 'armor', 12, 1200, NULL, NULL, 0, NULL, NULL, NULL, 10, 50, 'A modern LIGHT half suit. Half suits or vest types usually protect the upper body front, back, side, waist and groin. Concealed styles are tough thin armor designed to be sewn into clothes or hidden under them; the other half suits are generally bulky or worn atop clothes. All modern armor is designed for flexibility and mobility and does not interfere with movement, prowl or speed. The table is on printed 223 and its notes run onto 224.', 'Nightbane RPG p.223'),
  ('riot-jacket-nb', 'Riot Jacket', 'nightbane', 'armor', 12, 900, NULL, NULL, 0, NULL, NULL, NULL, 10, 60, 'A modern LIGHT half suit, printed 223.', 'Nightbane RPG p.223'),
  ('armor-vest-nb', 'Armor Vest', 'nightbane', 'armor', 10, 800, NULL, NULL, 0, NULL, NULL, NULL, 10, 50, 'A modern LIGHT half suit. Printed 223 heads this row simply Vest; named in full here so it is legible out of the table.', 'Nightbane RPG p.223'),
  ('point-blank-vest-nb', 'Point Blank Vest', 'nightbane', 'armor', 14, 1100, NULL, NULL, 0, NULL, NULL, NULL, 10, 70, 'A modern LIGHT half suit, printed 223.', 'Nightbane RPG p.223'),
  ('hard-armor-vest-nb', 'Hard Armor Vest', 'nightbane', 'armor', 15, 1400, NULL, NULL, 0, NULL, NULL, NULL, 12, 120, 'A modern LIGHT half suit, printed 223. Printed 224: hard armor is composed of ceramics (pure alumina or boron carbide), often combined with steel, provides the most effective protection and can even stop 7.62mm NATO and 5.56mm rifle bullets.', 'Nightbane RPG p.223'),
  ('frag-cape-vest-nb', 'Frag. Cape/Vest', 'nightbane', 'armor', 16, 1400, NULL, NULL, 0, NULL, NULL, NULL, 13, 120, 'A modern HEAVY full suit. Full suits are all bulky suits worn on top of clothes and provide the greatest protection (note on printed 224).', 'Nightbane RPG p.223'),
  ('riot-armor-nb', 'Riot Armor', 'nightbane', 'armor', 17, 1600, NULL, NULL, 0, NULL, NULL, NULL, 14, 180, 'A modern HEAVY full suit, printed 223.', 'Nightbane RPG p.223'),
  ('hard-armor-nb', 'Hard Armor', 'nightbane', 'armor', 20, 2200, NULL, NULL, 0, NULL, NULL, NULL, 16, 260, 'A modern HEAVY full suit, printed 223. Printed 224: hard armor is composed of ceramics (pure alumina or boron carbide), often combined with steel, provides the most effective protection and can even stop 7.62mm NATO and 5.56mm rifle bullets.', 'Nightbane RPG p.223'),
  ('class-4-armor-nb', 'Class 4 Armor', 'nightbane', 'armor', 20, 2800, NULL, NULL, 0, NULL, NULL, NULL, 17, 280, 'A modern HEAVY full suit, printed 223.', 'Nightbane RPG p.223'),
  ('binocular-best-magnification-nb', 'Binocular, best magnification', 'nightbane', 'gear', NULL, 1600, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Range 2000ft. Binocular and telescopic sights magnify an image area through a system of lenses. Printed 224.', 'Nightbane RPG p.224'),
  ('binocular-medium-magnification-nb', 'Binocular, medium magnification', 'nightbane', 'gear', NULL, 1000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Range 1600ft. Printed 224.', 'Nightbane RPG p.224'),
  ('binocular-low-magnification-nb', 'Binocular, low magnification', 'nightbane', 'gear', NULL, 600, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Range 1600ft. Printed 224.', 'Nightbane RPG p.224'),
  ('weapon-sight-best-magnification-nb', 'Weapon Sight, best magnification', 'nightbane', 'gear', NULL, 800, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 224.', 'Nightbane RPG p.224'),
  ('weapon-sight-medium-magnification-nb', 'Weapon Sight, medium magnification', 'nightbane', 'gear', NULL, 400, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 224.', 'Nightbane RPG p.224'),
  ('weapon-sight-low-magnification-nb', 'Weapon Sight, low magnification', 'nightbane', 'gear', NULL, 230, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Printed 224.', 'Nightbane RPG p.224'),
  ('infrared-goggles-mercury-battery-type-nb', 'Infrared Goggles (mercury battery type)', 'nightbane', 'gear', NULL, 550, 'fair availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Range 1200ft (360m). An infrared system relies on a source of infrared light, usually a pencil-thin beam projected from the goggles or binoculars, to illuminate its targets. THE BEAM LIMITS THE VIEW to a small area of about two square meters (7ft), making surveying a large area a problem, and is clearly visible to another infrared optic system, giving away the operator''s position. Both drawbacks are inherent to ALL infrared systems. The introductory paragraph gives the system ''Cost: about $1000; fair availability''; the table''s itemised prices are stored.', 'Nightbane RPG p.224'),
  ('infrared-goggles-new-superior-type-nb', 'Infrared Goggles (new superior type)', 'nightbane', 'gear', NULL, 880, 'fair availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Range 1200ft (360m). Printed 224.', 'Nightbane RPG p.224'),
  ('infrared-binoculars-nb', 'Infrared Binoculars', 'nightbane', 'gear', NULL, 2100, 'fair availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Range 1200ft (360m). Printed 224.', 'Nightbane RPG p.224'),
  ('infrared-monocular-eyepiece-nb', 'Infrared Monocular Eyepiece', 'nightbane', 'gear', NULL, 800, 'fair availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Range 1200ft (360m). Printed 224.', 'Nightbane RPG p.224'),
  ('infrared-weapon-sight-nb', 'Infrared Weapon Sight', 'nightbane', 'gear', NULL, 1200, 'fair availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Range 1200ft (360m). Printed 224.', 'Nightbane RPG p.224'),
  ('infrared-distancing-binoculars-nb', 'Infrared Distancing Binoculars', 'nightbane', 'gear', NULL, 6700, 'Not commercially available', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Range 2 miles (3km). A high-powered optical enhancement device with infrared adjustments, cross hair indicator lines and a digital readout of estimated distance and rate of travel. The I.D. binoculars are extremely popular among spies for field work and exploration, and are also used by the military.', 'Nightbane RPG p.224'),
  ('ultraviolet-optic-system-nb', 'Ultraviolet Optic System', 'nightbane', 'gear', NULL, 500, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Range 400ft (120m). Enables its wearer to see into the ultraviolet range of light radiation. Usually integrated into a larger optics package rather than used alone. Printed 224 heads it Ultraviolet Systems.', 'Nightbane RPG p.224'),
  ('night-sight-goggles-nb', 'Night Sight Goggles', 'nightbane', 'gear', NULL, 5200, 'poor availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Range 1600ft (480m). A night vision system is an image intensifier - a PASSIVE system that emits no light of its own and electronically amplifies existing ambient light to provide a visible picture. The introductory paragraph gives the system ''Cost: $1400; poor availability''; the table''s itemised prices are stored.', 'Nightbane RPG p.224'),
  ('night-sight-binoculars-nb', 'Night Sight Binoculars', 'nightbane', 'gear', NULL, 6400, 'poor availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Range 1600ft (480m). Printed 224.', 'Nightbane RPG p.224'),
  ('night-sight-monocular-eyepiece-nb', 'Night Sight Monocular Eyepiece', 'nightbane', 'gear', NULL, 1900, 'poor availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Range 1600ft (480m). Printed 224.', 'Nightbane RPG p.224');
INSERT INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, description, source_book)
