  ('night-sight-weapon-sight-nb', 'Night Sight Weapon Sight', 'nightbane', 'gear', NULL, 1800, 'poor availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Range 1600ft (480m). Printed 224.', 'Nightbane RPG p.224'),
  ('pocket-night-viewer-nb', 'Pocket Night Viewer', 'nightbane', 'gear', NULL, 800, 'THE BOOK PRICES THIS TWICE AND DIFFERENTLY. Its own description on printed 224 says $800; the Night Sights table on the same page lists it at $1500.00. The DESCRIPTION wins', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Range 800ft (240m). A mini night sight, usually a monocular style, easily concealed and portable. Poor availability.', 'Nightbane RPG p.224'),
  ('night-sight-large-tripod-mount-nb', 'Night Sight Large Tripod Mount', 'nightbane', 'gear', NULL, 14000, 'poor availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Night Sights (range 1600ft) table, printed 224.', 'Nightbane RPG p.224'),
  ('thermo-imager-goggles-nb', 'Thermo-Imager Goggles', 'nightbane', 'gear', NULL, 22000, 'poor availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Range 1600ft (480m). An optical heat sensor that converts the infrared radiation of warm objects into a visible image, letting its operator see in darkness, shadows and through smoke. Battery powered and electrically cooled, with a typical running life of 16 hours. THE INTRODUCTORY PARAGRAPH SAYS ''Cost: about $1400; poor availability'', an order of magnitude below every figure in its own table; the table''s itemised prices are stored and the paragraph''s figure is recorded here.', 'Nightbane RPG p.224'),
  ('thermo-imager-binoculars-nb', 'Thermo-Imager Binoculars', 'nightbane', 'gear', NULL, 20000, 'poor availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Range 1600ft (480m). Printed 224.', 'Nightbane RPG p.224'),
  ('thermo-imager-monocular-eyepiece-nb', 'Thermo-Imager Monocular Eyepiece', 'nightbane', 'gear', NULL, 18000, 'poor availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Range 1600ft (480m). Printed 224.', 'Nightbane RPG p.224'),
  ('thermo-imager-weapon-sight-nb', 'Thermo-Imager Weapon Sight', 'nightbane', 'gear', NULL, 18000, 'poor availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Range 1600ft (480m). Printed 224.', 'Nightbane RPG p.224'),
  ('multi-optics-helmet-m-o-h-nb', 'Multi-Optics Helmet (M.O.H.)', 'nightbane', 'gear', NULL, 38000, 'Available to high-tech organizations', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'An optical enhancement system built into a protective helmet: a targeting sight to 1600ft (480m), an infrared optics system to 1600ft (480m), a telescopic monocular lens to 2 miles (3km), and a thermo-imager to 1600ft (480m) that converts the infrared radiation of warm objects into a visible image, seeing in darkness, shadows and through smoke. SPECIAL BONUS: +1 to strike when the optics and targeting sight are engaged.', 'Nightbane RPG p.224'),
  ('optics-band-nb', 'Optics Band', 'nightbane', 'gear', NULL, 2800, NULL, NULL, 0, '7ft', NULL, NULL, NULL, NULL, 'A headband optical system most often used in research, micro-repairs and scientific study; its range is limited because it is designed for close work, not long-distance or combat surveillance. Infrared and ultraviolet optic system to 200ft (90m) maximum, a magnification lens to the 400th power with a range of 7ft (2m), a night sight to 200ft (90m), and adjustable color filters. The entry begins on printed 224 and its features and price are on 225.', 'Nightbane RPG p.224-225'),
  ('pocket-range-finder-nb', 'Pocket Range Finder', 'nightbane', 'gear', NULL, 58, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'A compact, easy to use optical range finder: look through the viewfinder and adjust the focus knob until the image is clear, and the range in feet AND meters appears below the target.', 'Nightbane RPG p.225'),
  ('illuminating-peglight-nb', 'Illuminating Peglight', 'nightbane', 'gear', NULL, 50, '$50 each', NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Designed for military use as markers for routes and minefields. Emits beta light, which gives off no heat and no infrared emissions. Can be seen from up to 150ft.', 'Nightbane RPG p.225');
